        "aiShortRec":  "พบ 1 ไซต์งาน Active จริงใน จ.อุดรธานี (ไซต์บ้านคุณจุ๊บ อ.โนนสะอาด คืบหน้า 70%) ยอดซื้อ SCG เติบโตสูงถึง ฿768.8K (+6,178% YoY)",
        "aiRecommendation":  "ผู้รับเหมาสร้างบ้านเติบโตสูงผิดปกติและมีคิวจองสร้างเต็มยาว แนะนำเร่งส่งมอบปูนเสือมอร์ตาร์และกระเบื้อง COTTO เข้าไซต์บ้านคุณจุ๊บ โนนสะอาด ด่วน",
        "customDiagnostic":  "ห้างหุ้นส่วนจำกัด รุ่งรัตน์บิวตี้โฮม เป็นผู้รับเหมา Mass Builder สายสปีดที่เติบโตแบบก้าวกระโดดสูงสุดในระบบ โดยมียอดซื้อ SCG เพิ่มขึ้นจาก ฿12,246 ในปี 2025 เป็น \u003cstrong\u003e฿768,825.5\u003c/strong\u003e ในปี 2026 (+6,178.2% YoY, SCG Code 10485682) มีสำนักงานใหญ่สาขา 1 อยู่ที่ อ.โนนสะอาด จ.อุดรธานี มีไซต์งานจริงในอุดรฯ ได้แก่ ไซต์บ้านคุณจุ๊บ อ.โนนสะอาด (แบบนอร์ดิก R223 คืบหน้า 70% ใน 76 วัน) และมีคิวจองสร้างบ้านเต็มยาวจนประกาศปิดรับงานชั่วคราว",
        "customRecommendations":  [
                                      "\u003cstrong\u003eปูนซีเมนต์สำเร็จรูป เสือ มอร์ตาร์ งานฉาบละเอียด (220 ถุง):\u003c/strong\u003e จัดส่งด่วนตรงถึงหน้างาน ต.โพธิ์ศรีสำราญ อ.โนนสะอาด รองรับงานฉาบเก็บผิวบ้านคุณจุ๊บ",
                                      "\u003cstrong\u003eกระเบื้องเซรามิก COTTO 120 ตร.ม. \u0026 ชุดสุขภัณฑ์ COTTO:\u003c/strong\u003e จัดทำ Mood Board กระเบื้องปูพื้นสไตล์นอร์ดิกให้คุณกิ๊ฟและน้องป๊อบ",
                                      "\u003cstrong\u003eแผ่นยิปซัมตราช้าง 9 มม. สำหรับแพ็กเกจฝ้าหลุมซ่อนไฟ:\u003c/strong\u003e ส่งมอบพร้อมโครงคร่าวโลหะช้างตรงตามสัญญาของแถม",
                                      "\u003cstrong\u003eข้อตกลงราคาเหมา Volume Rebate ประจำปี:\u003c/strong\u003e เจรจาสัญญาจัดส่งวัสดุต่อเนื่องสำหรับคิวงานก่อสร้างล่วงหน้าในเขตอุดรธานีและพื้นที่ใกล้เคียง"
                                  ],
